def cache_sim(capacity, ttl, ops):
    cache = {}  # {key: (value, write_time)}
    lru_order = []  # list of keys in LRU order (most recent at end)
    results = []

    def is_expired(key, current_time):
        if key not in cache:
            return True
        value, write_time = cache[key]
        return current_time >= write_time + ttl

    def mark_used(key):
        # Move key to end of lru_order (most recently used)
        if key in lru_order:
            lru_order.remove(key)
        lru_order.append(key)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries and evict if needed
            expired_keys = [k for k in cache if is_expired(k, t)]
            for k in expired_keys:
                del cache[k]
                if k in lru_order:
                    lru_order.remove(k)

            # If key is not in cache and cache is full, evict LRU
            if key not in cache and len(cache) >= capacity:
                lru_key = lru_order.pop(0)
                del cache[lru_key]

            # Put the key-value pair
            cache[key] = (value, t)
            mark_used(key)

        elif op[0] == 'get':
            _, t, key = op

            # Check if expired
            if key in cache and not is_expired(key, t):
                value, _ = cache[key]
                mark_used(key)
                results.append(value)
            else:
                results.append(-1)

    return results

